// path_is_directory: check whether the provided path refers to an existing directory.
// Inputs: path (path_t*) provided by runtime; pass by const reference per API.
// Outputs: return the same path object to keep it in the pool; also track result as an attribute.
{
    bool is_dir = path_is_directory(*path);
    // Record the observation for downstream stubs that may care about directory-ness.
    FUZZ_SET_ATTR_INT(path, "is_dir", is_dir ? 1 : 0);
    // No error condition to enforce beyond API call; function simply returns a bool.
    // Validation: Path object is preserved; attribute captures the result.
}

// list_directory: enumerate regular files and symlinks in dirpath.
// Inputs: dirpath (path_t*) which should ideally refer to a readable directory.
// Outputs: dirpath is returned unchanged; imagepaths is ephemeral and not returned.
{
    std::vector<path_t> imagepaths;
    // The function clears imagepaths internally; we provide an empty vector to start.
    int rc = list_directory(*dirpath, imagepaths);

    // Track the result count for potential follow-up checks in other stubs.
    FUZZ_SET_ATTR_INT(dirpath, "last_list_rc", rc);
    FUZZ_SET_ATTR_INT(dirpath, "last_list_count", (int)imagepaths.size());

    // API semantics: rc == 0 on success; -1 on failure (error printed to stderr).
    // We do not treat failure as a harness error; both paths are valid for fuzzing.
    // Validation: dirpath is preserved; attributes record rc and item count.
}

// filepath_is_readable: attempts to open the path for reading in binary mode.
// Inputs: path (path_t*).
// Outputs: original path preserved; annotate readability for downstream use.
{
    bool can_read = filepath_is_readable(*path);
    FUZZ_SET_ATTR_INT(path, "readable", can_read ? 1 : 0);
    // Validation: Function is side-effect-free beyond close-on-success; path object preserved.
}

// get_file_name_without_extension: string-only operation stripping the last '.' and any trailing '.'
// Inputs: path (path_t*) treated as a plain string.
// Outputs: original path is preserved; a new heap-allocated path_t holding the result is returned as out_noext.
path_t result_noext = get_file_name_without_extension(*path);
path_t *out_noext = new path_t(result_noext);
// Track length for potential downstream logic.
FUZZ_SET_ATTR_INT(out_noext, "len", (int)out_noext->size());
// Validation: Pure string transform; outputs are non-null and initialized; input preserved.

// get_file_extension: returns substring after the last '.'; empty if none or trailing '.'
// Inputs: path (path_t*) treated purely as a string.
// Outputs: original path preserved; new heap-allocated extension path_t returned as 'extension'.
path_t result_ext = get_file_extension(*path);
path_t *extension = new path_t(result_ext);
FUZZ_SET_ATTR_INT(extension, "len", (int)extension->size());
// Validation: Pure string transform; outputs are valid and preserved as required.

// get_executable_directory: returns the directory of the current executable with a trailing separator.
// Inputs: none.
// Outputs: heap-allocated path_t containing the directory with trailing separator.
path_t res = get_executable_directory();
path_t *execdir = new path_t(res);

// Property: If non-empty, last character should be a path separator. Use PATHSTR to match path_t's char type.
if (!execdir->empty()) {
    path_t seps = PATHSTR("/\\");
    auto last = execdir->back();
    bool ends_with_sep = (seps.find(last) != path_t::npos);
    FUZZ_ASSERT(ends_with_sep, "get_executable_directory() must end with a path separator");
}
// Validation: Output object allocated; trailing separator property asserted when applicable.

// sanitize_filepath: returns the path unchanged if readable; otherwise concatenates exec dir + path.
// Inputs: path (path_t*), treated as a string; relies on filepath_is_readable and get_executable_directory internally.
// Outputs: original path preserved; new heap-allocated sanitized path_t returned as 'sanitized'.
path_t res_sanitized = sanitize_filepath(*path);
path_t *sanitized = new path_t(res_sanitized);

// Record whether sanitization likely occurred by comparing equality.
int same = (*sanitized == *path) ? 1 : 0;
FUZZ_SET_ATTR_INT(sanitized, "same_as_input", same);
// Validation: Output allocated and initialized; input is preserved; simple equality attribute tracked.
